CREATE TABLE IF NOT EXISTS microredes (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS establecimientos (id INT PRIMARY KEY AUTO_INCREMENT, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(180) NOT NULL, microred_id INT NOT NULL, cod_distrito VARCHAR(30) NOT NULL, distrito VARCHAR(150) NOT NULL, categoria VARCHAR(30) NOT NULL, FOREIGN KEY (microred_id) REFERENCES microredes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usuarios (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(150) NOT NULL, usuario VARCHAR(80) NOT NULL UNIQUE, clave VARCHAR(255) NOT NULL, rol ENUM('admin','tecnico','microred','establecimiento') NOT NULL, microred_id INT NULL, establecimiento_id INT NULL UNIQUE, activo TINYINT NOT NULL DEFAULT 1, intentos INT NOT NULL DEFAULT 0, bloqueo_hasta DATETIME NULL, telefono_1 VARCHAR(30) NULL DEFAULT NULL, telefono_2 VARCHAR(30) NULL DEFAULT NULL, correo VARCHAR(254) NULL DEFAULT NULL, FOREIGN KEY (microred_id) REFERENCES microredes(id), FOREIGN KEY (establecimiento_id) REFERENCES establecimientos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS productos (id INT PRIMARY KEY AUTO_INCREMENT, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(255) NOT NULL, tipo VARCHAR(20) NOT NULL, unidad VARCHAR(60) NOT NULL, fecha_vencimiento DATE NULL DEFAULT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS instalacion (id INT PRIMARY KEY, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS imi_apertura (establecimiento_id INT NOT NULL, producto_id INT NOT NULL, saldo BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(establecimiento_id,producto_id), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_reportes (id INT PRIMARY KEY AUTO_INCREMENT, establecimiento_id INT NOT NULL, periodo DATE NOT NULL, estado ENUM('borrador','enviado') NOT NULL DEFAULT 'borrador', version INT NOT NULL DEFAULT 1, actualizado_por INT NULL, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unico_mes(establecimiento_id,periodo), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(actualizado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_detalles (reporte_id INT NOT NULL, producto_id INT NOT NULL, stock_segun BIGINT UNSIGNED NOT NULL, recibido BIGINT UNSIGNED NOT NULL, consumo BIGINT UNSIGNED NOT NULL, ajuste BIGINT UNSIGNED NOT NULL, stock_inicial BIGINT UNSIGNED NOT NULL, stock_final BIGINT UNSIGNED NOT NULL, PRIMARY KEY(reporte_id,producto_id), FOREIGN KEY(reporte_id) REFERENCES imi_reportes(id) ON DELETE CASCADE, FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS imi_periodos (periodo DATE PRIMARY KEY, estado ENUM('abierto','cerrado') NOT NULL DEFAULT 'cerrado', inicio DATETIME NULL, fin DATETIME NULL, version INT NOT NULL DEFAULT 1, actualizado_por INT NULL, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(actualizado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS dist_control (id INT PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dist_estrategias (id INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dist_areas (id INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dist_almacen (producto_id INT PRIMARY KEY,saldo BIGINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dist_programaciones (id INT PRIMARY KEY AUTO_INCREMENT,anio INT NOT NULL,numero INT NOT NULL,estrategia_id INT NOT NULL,area_id INT NOT NULL,meses INT NOT NULL,estado ENUM('borrador','cerrado') NOT NULL DEFAULT 'borrador',version INT NOT NULL DEFAULT 1,creado_por INT NULL,cerrado_por INT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,cerrado_en DATETIME NULL,fecha_cierre DATE NULL,UNIQUE KEY numero_anual(anio,numero),FOREIGN KEY(estrategia_id) REFERENCES dist_estrategias(id),FOREIGN KEY(area_id) REFERENCES dist_areas(id),FOREIGN KEY(creado_por) REFERENCES usuarios(id) ON DELETE SET NULL,FOREIGN KEY(cerrado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dist_detalles (programacion_id INT NOT NULL,producto_id INT NOT NULL,establecimiento_id INT NOT NULL,cantidad BIGINT UNSIGNED NOT NULL,fuente_id INT NULL,fuente_version INT NULL,fuente_periodo DATE NULL,fuente_fecha DATETIME NULL,stock BIGINT NULL,cpma DECIMAL(18,8) NULL,cobertura DECIMAL(24,8) NULL,indicador VARCHAR(24) NOT NULL,pendiente_antes BIGINT UNSIGNED NOT NULL DEFAULT 0,sugerida BIGINT UNSIGNED NULL,observacion VARCHAR(250) NOT NULL DEFAULT '',pendiente_verificado_id INT NULL,pendiente_verificado_version INT NULL,verificado_en DATETIME NULL,verificado_por INT NULL,incorporado_reporte_id INT NULL,incorporado_version INT NULL,incorporado_en DATETIME NULL,incorporado_por INT NULL,PRIMARY KEY(programacion_id,producto_id,establecimiento_id),FOREIGN KEY(programacion_id) REFERENCES dist_programaciones(id),FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id),FOREIGN KEY(incorporado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dist_movimientos (id INT PRIMARY KEY AUTO_INCREMENT,producto_id INT NOT NULL,programacion_id INT NULL,tipo ENUM('ingreso','ajuste','salida') NOT NULL,cantidad BIGINT NOT NULL,saldo_antes BIGINT UNSIGNED NOT NULL,saldo_despues BIGINT UNSIGNED NOT NULL,referencia VARCHAR(200) NOT NULL,solicitud VARCHAR(80) NOT NULL UNIQUE,creado_por INT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(programacion_id) REFERENCES dist_programaciones(id),FOREIGN KEY(creado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

